import functools

def semver_sort(versions):
    def parse(v):
        main = v
        if '+' in main:
            idx = main.index('+')
            main = main[:idx]
        if '-' in main:
            idx = main.index('-')
            core = main[:idx]
            pre = main[idx+1:]
        else:
            core = main
            pre = None
        major, minor, patch = map(int, core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_pre(a, b):
        if a is None and b is None:
            return 0
        if a is None:
            return 1  # no prerelease has higher precedence
        if b is None:
            return -1
        for x, y in zip(a, b):
            if x == y:
                continue
            x_num = x.isdigit()
            y_num = y.isdigit()
            if x_num and y_num:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
                continue
            if x_num and not y_num:
                return -1
            if not x_num and y_num:
                return 1
            return -1 if x < y else 1
        if len(a) == len(b):
            return 0
        return -1 if len(a) < len(b) else 1

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        if p1[0] != p2[0]:
            return -1 if p1[0] < p2[0] else 1
        if p1[1] != p2[1]:
            return -1 if p1[1] < p2[1] else 1
        if p1[2] != p2[2]:
            return -1 if p1[2] < p2[2] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

